param([ValidateSet('Scan','WindowsUpdate','Backup','Official','BIOS')][string]$Mode,[string]$BackupDir)
if($Mode -eq 'Scan'){Get-CimInstance Win32_PnPSignedDriver|Where-Object {$_.DeviceName -and $_.DriverVersion}|Sort-Object DeviceName|Select-Object DeviceName,Manufacturer,DriverVersion,@{N='Date';E={$_.DriverDate}}|Format-Table -AutoSize;exit}
if($Mode -eq 'Backup'){$d=Join-Path $BackupDir ('Drivers_'+(Get-Date -Format yyyyMMdd_HHmmss));New-Item $d -ItemType Directory -Force|Out-Null;pnputil /export-driver * $d;Write-Host ('Backup: '+$d);exit}
if($Mode -eq 'WindowsUpdate'){Write-Host 'Opening Windows Update > Optional updates.';Start-Process 'ms-settings:windowsupdate-optionalupdates';exit}
$cs=Get-CimInstance Win32_ComputerSystem;$gpu=Get-CimInstance Win32_VideoController|Select-Object -First 1;$bios=Get-CimInstance Win32_BIOS
if($Mode -eq 'BIOS'){Write-Host ('Manufacturer: '+$cs.Manufacturer);Write-Host ('Model: '+$cs.Model);Write-Host ('BIOS: '+$bios.SMBIOSBIOSVersion+' | '+$bios.ReleaseDate);Write-Host 'WinTool does not automatically download or install BIOS.';exit}
Write-Host ('System: '+$cs.Manufacturer+' '+$cs.Model);Write-Host ('GPU: '+$gpu.Name);$urls=@();if($gpu.Name -match 'AMD|Radeon'){$urls+='https://www.amd.com/en/support/download/drivers.html'};if($gpu.Name -match 'NVIDIA'){$urls+='https://www.nvidia.com/Download/index.aspx'};if($gpu.Name -match 'Intel'){$urls+='https://www.intel.com/content/www/us/en/support/detect.html'};if($cs.Manufacturer -match 'Micro-Star|MSI'){$urls+='https://www.msi.com/support'};if(!$urls){Write-Host 'No specific support page could be identified safely. Use the manufacturer official website.'}else{$urls|ForEach-Object{Write-Host ('OFFICIAL: '+$_);$a=Read-Host 'Open this page? [Y/N]';if($a -match '^[Yy]'){Start-Process $_}}}
